    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n  a.*,\n  s.Nume, s.CNP, s.Judet, \n  j.NumeJudet, j.CodJudet,\n  s.CodPlata, o.DenumireSuperior, s.CodLocMunca, o.DenumireInferior,\n  sca.*\nFROM app.CalculAgent a\nLEFT JOIN app.Salariat s\n  ON s.Marca = a.Marca\n AND s.CodSucursala = a.CodSucursala\n AND s.Anul = a.Anul\n AND s.Luna = a.Luna\nLEFT JOIN app.NomJudet j\n  ON j.CodSucursala = a.CodSucursala\n AND j.CodJudet = s.Judet\nLEFT JOIN app.NomOrganigrama o \n  ON s.CodLocMunca = o.CodInferior\n AND o.CodSucursala = a.CodSucursala\n AND o.Anul = a.Anul\n AND o.Luna = a.Luna\nLEFT JOIN app.StatusCalcul sca\n  ON ISNULL(a.Status, 1) = sca.Id \nWHERE a.CodSucursala = @CodSucursala\n  AND a.Anul = @AnSesiune\n  AND a.Luna = @LunaSesiune;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;AnSesiune&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;LunaSesiune&quot;}],&quot;IdColumn&quot;:&quot;Id&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;Id&quot;,&quot;Name&quot;:&quot;Id&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullabl