    &lt;GridButtons&gt;[{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Left&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;3606351d-8e67-46b1-82b6-b5e87474e61f&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;/* ========= CSAG - Informix faithful version (ROUND half-up) ========= */\n\n;WITH BrutRaw AS (\n    /* 1️⃣ Brut cu zecimale */\n    SELECT\n        a.Marca,\n\n        SUM(\n            CASE\n                WHEN UPPER(a.CodPrestatie) &amp;lt;&amp;gt; &#39;E&#39;\n                     AND ISNULL(a.Procent, 0) &amp;lt;&amp;gt; 0\n                THEN a.Suma * a.Procent\n\n                WHEN UPPER(a.CodPrestatie) &amp;lt;&amp;gt; &#39;E&#39;\n                     AND ISNULL(a.Procent, 0) = 0\n                THEN ISNULL(p.SumaFixa, 0) * a.Suma\n\n                ELSE 0\n            END\n        ) AS BrutDecimal,\n\n        SUM(\n            CASE\n                WHEN UPPER(a.CodPrestatie) = &#39;E&#39;\n                THEN a.Suma * a.Procent\n                ELSE 0\n            END\n        ) AS TutunDecimal\n\n    FROM app.Agent a\n\n    OUTER APPLY (\n        SELECT TOP 1 p.SumaFixa\n        FROM app.TSPrestatie p\n        WHERE p.CodSucursala = a.CodSucursala\n          AND p.CodPrestatie = a.CodPrestatie\n    ) p\n\n    WHERE a.CodSucursala = @CodSucursala\n      AND a.Anul = @An\n      AND a.Luna = @Luna\n\n    GROUP BY a.Marca\n),\n\nBrut AS (\n    /* 2️⃣ ROUND exact ca dec(15,0) */\n    SELECT\n        Marca,\n        CAST(ROUND(BrutDecimal, 0) AS INT)  AS BrutFaraE,\n        CAST(ROUND(TutunDecimal, 0) AS INT) AS Tutun\n    FROM BrutRaw\n),\n\nCuTransa AS (\n    /* 3️⃣ Determinare tranșă */\n    SELECT\n        b.*,\n        l.LimitaInferioara AS LimiCurenta,\n        l.LimitaSuperioara,\n        l.Procent AS ProcCurent\n    FROM Brut b\n    OUTER APPLY (\n        SELECT TOP 1 *\n        FROM app.LimitaPrestatiiAg l\n        WHERE b.BrutFaraE BETWEEN l.LimitaInferioara AND l.LimitaSuperioara\n        ORDER BY l.LimitaInferioara DESC\n    ) l\n),\n\nSel1Raw AS (\n    /* 4️⃣ Sel1 cu zecimale */\n    SELECT\n        x.Marca,\n        SUM(\n            (l.LimitaSuperioara - l.LimitaInferioara + 1)\n            * l.Procent\n        ) AS Sel1Decimal\n    FROM CuTransa x\n    JOIN app.LimitaPrestatiiAg l\n      ON l.LimitaInferioara &amp;lt; x.LimiCurenta\n    GROUP BY x.Marca\n),\n\nSel1 AS (\n    /* 5️⃣ ROUND exact ca &#238;n Informix */\n    SELECT\n        Marca,\n        CAST(ROUND(ISNULL(Sel1Decimal, 0), 0) AS INT) AS Sel1\n    FROM Sel1Raw\n),\n\nRezultat AS (\n    /* 6️⃣ Aplicare progresiv exact ca &#238;n 4GL */\n    SELECT\n        x.Marca,\n        x.BrutFaraE,\n        ISNULL(s.Sel1, 0) AS Sel1,\n        x.Tutun,\n\n        /* partea din tranșa curentă – ROUND half-up */\n        CAST(\n            ROUND(\n                (x.BrutFaraE - x.LimiCurenta)\n                * x.ProcCurent\n            , 0)\n        AS INT) AS ParteCurenta,\n\n        /* total final */\n        CAST(\n            ROUND(\n                (x.BrutFaraE - x.LimiCurenta)\n                * x.ProcCurent\n            , 0)\n        AS INT)\n        + ISNULL(s.Sel1, 0)\n        + x.Tutun AS TotalFinal\n\n    FROM CuTransa x\n    LEFT JOIN Sel1 s ON s.Marca = x.Marca\n)\n\n/* ================= MERGE ================= */\n\nMERGE app.CalculAgent AS tgt\nUSING (\n    SELECT\n        @CodSucursala AS CodSucursala,\n        @An           AS Anul,\n        @Luna         AS Luna,\n        Marca,\n        TotalFinal\n    FROM Rezultat\n) AS src\nON  tgt.CodSucursala = src.CodSucursala\nAND tgt.Anul         = src.Anul\nAND tgt.Luna         = src.Luna\nAND tgt.Marca        = src.Marca\n\n/* 1. UPDATE: Agentul există deja. Actualizăm suma și forțăm Status = 1 (Draft) */\nWHEN MATCHED THEN\n    UPDATE SET\n        tgt.Suma = src.TotalFinal,\n        tgt.Status = 1, /* &amp;lt;--- AM ADĂUGAT AICI */\n        tgt.LastModifiedDate = SYSDATETIMEOFFSET(),\n        tgt.LastModifiedBy = @UserId\n\n/* 2. INSERT: Agentul este nou. &#206;l adăugăm cu Status = 1 (Draft) */\nWHEN NOT MATCHED THEN\n    INSERT (\n        CodSucursala,\n        Anul,\n        Luna,\n        Marca,\n        Suma,\n        Status, /* &amp;lt;--- AM ADĂUGAT AICI */\n        CreatedDate,\n        CreatedBy\n    )\n    VALUES (\n        src.CodSucursala,\n        src.Anul,\n        src.Luna,\n        src.Marca,\n        src.TotalFinal,\n        1,      /* &amp;lt;--- AM ADĂUGAT AICI (1 = Draft) */\n        SYSDATETIMEOFFSET(),\n        @UserId\n    )\n\n/* 3. DELETE: Agentul a dispărut din sursă. &#206;l ștergem din calculul curent */\nWHEN NOT MATCHED BY SOURCE \n     AND tgt.CodSucursala = @CodSucursala \n     AND tgt.Anul = @An \n     AND tgt.Luna = @Luna \nTHEN \n    DELETE;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;An&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserId]&quot;,&quot;name&quot;:&quot;UserId&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;3af4eb9f-c02d-4808-8c51-81734ea48796&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;a351e975-5310-49f7-9c57-d275ff25d22d&quot;}},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=CalculSume&quot;,&quot;ModuleId&quot;:884,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;CalculSume&quot;,&quot;Title&quot;:&quot;Calcul Sume&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:&quot;0&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;primary&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Left&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;6b1444da-6ee1-42b0-94f9-7829a3757975&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;OpenAFPopup&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;29ca58c1-735e-4121-a570-69e58d03aa5a&quot;},&quot;ReinitForm&quot;:true,&quot;Params&quot;:null,&quot;AllowUserClose&quot;:true,&quot;CloseOnClick&quot;:true,&quot;CloseOnEscape&quot;:true},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Add.OpenForm&quot;},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Add&quot;,&quot;ModuleId&quot;:884,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;Add&quot;,&quot;Title&quot;:&quot;Adauga Manual Calcul Agent&quot;,